-- ADELE CLEAN SUPABASE SETUP v1. SQL Editor ready. No historical rows or credentials.
-- Creates/validates 18 tables in adele_private only. Does not drop or truncate application objects.
-- Rerunnable for this setup; an unrelated/older schema or incompatible drift aborts atomically.
-- Backend financial writes remain disabled by BOTH role privileges and the existing Node policy gate.
BEGIN;
SET LOCAL search_path = pg_catalog;
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(16428, 20261021);
DO $gate$
BEGIN
 IF EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='adele_private' AND obj_description(oid,'pg_namespace') IS DISTINCT FROM 'ADELE clean setup v1: empty start, no historical import') THEN
  RAISE EXCEPTION 'adele_private already exists outside this clean setup. Use an empty target; nothing will be deleted automatically.';
 END IF;
END $gate$;
CREATE SCHEMA IF NOT EXISTS adele_private;
COMMENT ON SCHEMA adele_private IS 'ADELE clean setup v1: empty start, no historical import';
REVOKE ALL ON SCHEMA adele_private FROM PUBLIC;
CREATE COLLATION IF NOT EXISTS adele_private.adele_ci (provider=icu,locale='und-u-ks-level1',deterministic=false);
DO $collation$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_collation c JOIN pg_namespace n ON n.oid=c.collnamespace WHERE n.nspname='adele_private' AND c.collname='adele_ci' AND c.collprovider='i' AND NOT c.collisdeterministic AND COALESCE(to_jsonb(c)->>'colliculocale',to_jsonb(c)->>'colllocale')='und-u-ks-level1') THEN
  RAISE EXCEPTION 'Unexpected ICU collation definition';
 END IF;
END $collation$;

CREATE TABLE IF NOT EXISTS adele_private."application_documents" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "application_id" varchar(20) COLLATE adele_private.adele_ci NOT NULL,
  "file_name" varchar(255) COLLATE adele_private.adele_ci NOT NULL,
  "file_path" varchar(500) COLLATE adele_private.adele_ci NOT NULL,
  "mime_type" varchar(100) COLLATE adele_private.adele_ci NOT NULL DEFAULT 'application/pdf',
  "size" bigint NOT NULL DEFAULT 0,
  "uploaded_at" timestamp(0) without time zone NOT NULL DEFAULT LOCALTIMESTAMP(0),
  CONSTRAINT "application_documents_pkey" PRIMARY KEY ("id")
);
ALTER TABLE adele_private."application_documents" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS adele_private."audit_logs" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" integer,
  "user_name" varchar(255) COLLATE adele_private.adele_ci,
  "action" varchar(100) COLLATE adele_private.adele_ci NOT NULL,
  "description" text COLLATE adele_private.adele_ci,
  "related_record" varchar(255) COLLATE adele_private.adele_ci,
  "created_at" timestamp(0) without time zone NOT NULL DEFAULT LOCALTIMESTAMP(0),
  CONSTRAINT "audit_logs_pkey" PRIMARY KEY ("id")
);
ALTER TABLE adele_private."audit_logs" ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS adele_private."contact_messages" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name" varchar(120) COLLATE adele_private.adele_ci NOT NULL,
  "email" varchar(255) COLLATE adele_private.adele_ci NOT NULL,
  "subject" varchar(160) COLLATE adele_private.adele_ci NOT NULL,
  "message" text COLLATE adele_private.adele_ci NOT NULL,
  "status" varchar(20) COLLATE adele_private.adele_ci NOT NULL DEFAULT 'new',
  "created_at" timestamp(0) without time zone NOT NULL DEFAULT LOCALTIMESTAMP(0),
  CONSTRAINT "contact_messages_pkey" PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "contact_messages_idx_contact_status" ON adele_private."contact_messages" ("status", "created_at");
ALTER TABLE adele_private."contact_messages" ENABLE ROW LEVEL SECURITY;

