"amount\" IS NULL OR (\"amount\">=0 AND \"amount\" NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric))"},{"table_name":"repayment_schedules","constraint_name":"ck_repayment_schedules_amount_finite_nonnegative","expression":"\"amount\" IS NULL OR (\"amount\">=0 AND \"amount\" NOT IN ('NaN'::numeric,'Infinity'::numeric,'-Infinity'::numeric))"},{"table_name":"loans","constraint_name":"ck_loans_total","expression":"principal + interest = total_payable"},{"table_name":"loans","constraint_name":"ck_loans_balance","expression":"amount_paid + outstanding_balance = total_payable"},{"table_name":"application_documents","constraint_name":"ck_application_documents_size","expression":"size >= 0"},{"table_name":"loans","constraint_name":"ck_loans_duration_dates","expression":"duration > 0 AND due_date >= start_date"},{"table_name":"sessions","constraint_name":"ck_sessions_hashed_identifier","expression":"id::text COLLATE \"C\" ~ '^[0-9a-f]{64}$'"}]$contract$::jsonb) AS x(table_name text,constraint_name text,expression text) LOOP
  target=to_regclass(format('adele_private.%I',r.table_name));
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=target AND conname=r.constraint_name) THEN
   EXECUTE format('ALTER TABLE adele_private.%I ADD CONSTRAINT %I CHECK (%s)',r.table_name,r.constraint_name,r.expression);
  END IF;
  counter=counter+1;probe='_adele_clean_probe_'||counter;
  EXECUTE format('CREATE TEMP TABLE %I (LIKE adele_private.%I) ON COMMIT DROP',probe,r.table_name);
  EXECUTE format('ALTER TABLE pg_temp.%I ADD CONSTRAINT expected_check CHECK (%s)',probe,r.expression);
  SELECT pg_get_expr(conbin,conrelid) INTO expected_expression FROM pg_constraint WHERE conrelid=to_regclass(format('pg_temp.%I',probe)) AND conname='expected_check';
  SELECT pg_get_expr(conbin,conrelid) INTO actual_expression FROM pg_constraint WHERE conrelid=target AND conname=r.constraint_name AND contype='c' AND convalidated;
  IF actual_expression IS DISTINCT FROM expected_expression THEN RAISE EXCEPTION 'CHECK constraint drift on %.%',r.table_name,r.constraint_name; END IF;
 END LOOP;
END $checks$;
CREATE SEQUENCE IF NOT EXISTS adele_private.business_customers AS bigint MAXVALUE 9999999999999999 START WITH 1;
CREATE SEQUENCE IF NOT EXISTS adele_private.business_loan_applications AS bigint MAXVALUE 9999999999999999 START WITH 1;
CREATE SEQUENCE IF NOT EXISTS adele_private.business_loans AS bigint MAXVALUE 9999999999999999 START WITH 1;
CREATE SEQUENCE IF NOT EXISTS adele_private.business_repayments AS bigint MAXVALUE 9999999999999999 START WITH 1;
CREATE SEQUENCE IF NOT EXISTS adele_private.business_payments AS bigint MAXVALUE 9999999999999999 START WITH 1;
CREATE SEQUENCE IF NOT EXISTS adele_private.business_incomes AS bigint MAXVALUE 9999999999999999 START WITH 1;
CREATE SEQUENCE IF NOT EXISTS adele_private.business_expenses AS bigint MAXVALUE 9999999999999999 START WITH 1;
-- Non-login privilege group only: no passwords, application users or active sessions created.
DO $backend_role$
DECLARE r record;
BEGIN
 SELECT * INTO r FROM pg_roles WHERE rolname='adele_backend';
 IF NOT FOUND THEN
  CREATE ROLE adele_backend NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  COMMENT ON ROLE adele_backend IS 'ADELE clean setup backend privilege group v1';
 ELSE
  IF shobj_description(r.oid,'pg_authid') IS DISTINCT FROM 'ADELE clean setup backend privilege group v1' OR r.rolcanlogin OR r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication OR r.rolbypassrls THEN
   RAISE EXCEPTION 'Existing adele_backend role is not the expected restricted non-login group';
  END IF;
 END IF;
END $backend_role$;
REVOKE ALL ON ALL TABLES IN SCHEMA adele_private FROM PUBLIC,adele_backend;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA adele_private FROM PUBLIC,adele_backend;
GRANT USAGE ON SCHEMA adele_private TO adele_backend;
GRANT SELECT ON ALL TABLES IN SCHEMA adele_private TO adele_backend;
GRANT INSERT,UPDATE,DELETE ON adele_private.users,adele_private.roles,adele_private.sessions,adele_private.login_attempts,adele_private.revoked_tokens TO adele_backend;
GRANT INSERT ON adele_private.audit_logs TO adele_backend;
GRANT INSERT,UPDATE ON adele_private.contact_messages TO adele_backend;
GRANT USAGE,SELECT ON SEQUENCE adele_private.users_id_seq TO adele_backend;
GRANT USAGE,SELECT ON SEQUENCE adele_private.roles_id_seq TO adele_backend;
GRANT USAGE,SELECT ON SEQUENCE adele_private.login_attempts_id_seq TO adele_backend;
GRANT USAGE,SELECT ON SEQUENCE adele_private.audit_logs_id_seq TO adele_backend;
GRANT USAGE,SELECT ON SEQUENCE adele_private.contact_messages_id_seq TO adele_backend;
DO $security$
DECLARE r text; t record; p record; backend_oid oid;
BEGIN
 SELECT oid INTO backend_oid FROM pg_roles WHERE rolname='adele_backend';
 FOR t IN SELECT oid,relname FROM pg_class WHERE relnamespace='adele_private'::regnamespace AND relkind='r' LOOP
  EXECUTE format('ALTER TABLE adele_private.%I ENABLE ROW LEVEL SECURITY',t.relname);
  IF NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=t.oid AND polname='adele_backend_access') THEN
   EXECUTE format('CREATE POLICY adele_backend_access ON adele_private.%I FOR ALL TO adele_backend USING (true) WITH CHECK (true)',t.relname);
  END IF;
  SELECT * INTO p FROM pg_policy WHERE polrelid=t.oid AND polname='adele_backend_access';
  IF p.polcmd<>'*' OR NOT p.polpermissive OR p.polroles<>ARRAY[backend_oid] OR pg_get_expr(p.polqual,p.polrelid)<>'true' OR pg_get_expr(p.polwithcheck,p.polrelid)<>'true' OR (SELECT count(*) FROM pg_policy WHERE polrelid=t.oid)<>1 THEN
   RAISE EXCEPTION 'Unexpected RLS policy on %',t.relname;
  END IF;
 END LOOP;
 FOREACH r IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=r) THEN
   IF pg_has_role(r,'adele_backend','MEMBER') THEN RAISE EXCEPTION 'Browser/service role must not inherit adele_backend privileges'; END IF;
   EXECUTE format('REVOKE ALL ON SCHEMA adele_private FROM %I',r);
   EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA adele_private FROM %I',r);
   EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA adele_private FROM %I',r);
  END IF;
 END LOOP;
END $security$;
ALTER DEFAULT PRIVILEGES IN SCHEMA adele_private REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES IN SCHEMA adele_private REVOKE ALL ON SEQUENCES FROM PUBLIC;
COMMIT;
SELECT 'ADELE clean schema ready; financial writes remain disabled' AS status,18 AS expected_tables;
